    assert_eq!(responses[4]["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(responses[5]["Counts"]["Visible"], 0);
    assert_eq!(responses[6]["Messages"], json!([]));
    assert_eq!(responses[7]["Counts"]["Visible"], 0);
